/**
 * Assembles the Learn v2 catalogue from the authoring sources: modules,
 * topics (with resource and quiz references), quiz practice items, the
 * problems index (problems.json, generated by scripts/build-problems.ts from
 * the LeetCode company dataset) and the 12 starter projects.
 */
import type { LearningResource, PracticeItem } from '../../../src/types';
import type { LearnModule, LearnTopic, ProblemInfo, Project } from '../../../src/v2/types';
import { PRACTICE_ITEMS } from '../practice';
import { RESOURCE_DEFS } from '../resources';
import { APTITUDE_MODULES, CORE_MODULES, INTERVIEW_MODULES, V2_SKILL_DEFS } from './core';
import type { ModuleDef } from './defs';
import { buildDevModules } from './dev';
import { DSA_MODULES, LANGUAGE_MODULES } from './dsa';
import { PROJECT_DEFS } from './projects';
import { V2_RESOURCE_DEFS } from './resources';
import problemsJson from './problems.json';
import linkStatus from './link-status.json';

export { V2_SKILL_DEFS };

export function allModuleDefs(): ModuleDef[] {
  return [...LANGUAGE_MODULES, ...DSA_MODULES, ...CORE_MODULES, ...APTITUDE_MODULES, ...INTERVIEW_MODULES, ...buildDevModules()];
}

/** Every curated problem slug (must, good and stretch), in catalogue order. */
export function curatedSlugs(defs: ModuleDef[] = allModuleDefs()): string[] {
  const out: string[] = [];
  for (const m of defs)
    for (const t of m.topics)
      for (const s of [t.must, t.good, t.stretch].flatMap((x) => (x ?? '').split(/\s+/).filter(Boolean)))
        if (!out.includes(s)) out.push(s);
  return out;
}

const refs = (s?: string) => (s ?? '').split(/\s+/).filter(Boolean).map((x) => `lc:${x}`);

type LinkStatus = Record<string, { status: LearningResource['status']; http_status: number | null; last_checked: string }>;

/** v2 resources with any link-check results applied. */
export function v2Resources() {
  const status = linkStatus as LinkStatus;
  return V2_RESOURCE_DEFS.map((r) => {
    const s = status[r.id];
    return s ? { ...r, status: s.status, http_status: s.http_status, last_checked: s.last_checked } : r;
  });
}

export interface V2Content {
  modules: LearnModule[];
  topics: LearnTopic[];
  practice_items: PracticeItem[];
  problems: ProblemInfo[];
  projects: Project[];
}

export function buildV2Content(): V2Content {
  const defs = allModuleDefs();
  const allResources = [...RESOURCE_DEFS, ...V2_RESOURCE_DEFS];
  const resourceIds = new Set(allResources.map((r) => r.id));
  const modules: LearnModule[] = [];
  const topics: LearnTopic[] = [];
  const practice_items: PracticeItem[] = [];

  for (const m of defs) {
    modules.push({
      id: m.id,
      title: m.title,
      summary: m.summary,
      stream: m.stream,
      role_families: m.roles ?? [],
      aims: m.aims ?? [],
      language: m.language ?? null,
      level: m.level,
      order: m.order,
      prerequisites: [
        ...(m.pre ?? []).map((module_id) => ({ module_id, kind: 'hard' as const })),
        ...(m.soft ?? []).map((module_id) => ({ module_id, kind: 'soft' as const })),
      ],
      skill_ids: m.skills,
      status: 'draft',
      ai_drafted: true,
      version: 1,
    });
    m.topics.forEach((t, order) => {
      const id = `${m.id}.${t.key}`;
      const skills = t.skills ?? [];
      // Dev topics reuse the skill's curated resources (best first); others use topic then module resources.
      const fromSkills = skills.length
        ? allResources
            .filter((r) => r.skill_ids.some((s) => skills.includes(s)))
            .sort((a, b) => b.quality - a.quality)
            .map((r) => r.id)
        : [];
      const resource_ids = [...new Set([...(t.res ?? []), ...fromSkills, ...(m.res ?? [])])]
        .filter((r) => resourceIds.has(r))
        .slice(0, 5);
      const quizIds: string[] = [];
      (t.quiz ?? []).forEach((q, i) => {
        const itemId = `${id}.q${i + 1}`;
        quizIds.push(itemId);
        const skill = skills[0] ?? m.skills[0];
        practice_items.push({
          id: itemId,
          skill_id: skill,
          lesson_id: `lesson-${skill}`,
          prompt: q.q,
          explanation: q.why,
          difficulty: 'easy',
          company_tags: [],
          status: 'draft',
          ai_drafted: true,
          version: 1,
          kind: 'mcq',
          options: q.options,
          correct: Array.isArray(q.answer) ? q.answer : [q.answer],
        });
      });
      // Dev topics also quiz on the skill's existing practice items (code items need a runner, so they are left out).
      for (const p of PRACTICE_ITEMS) if (skills.includes(p.skill_id) && p.kind !== 'code') quizIds.push(p.id);
      topics.push({
        id,
        module_id: m.id,
        order,
        title: t.title,
        summary_md: t.sum,
        key_points: t.pts,
        tier: t.tier ?? 'core',
        skill_ids: skills,
        resource_ids,
        learn_minutes: t.min,
        learn_kind: t.kind ?? 'learn',
        problems: { must: refs(t.must), good: refs(t.good), stretch: refs(t.stretch) },
        lc_tags: t.tags ?? [],
        quiz_item_ids: quizIds,
        tasks: (t.tasks ?? []).map((k) => ({ ...k, optional: k.optional ?? false })),
        status: 'draft',
        ai_drafted: true,
      });
    });
  }
  return {
    modules,
    topics,
    practice_items,
    problems: problemsJson as ProblemInfo[],
    projects: PROJECT_DEFS as Project[],
  };
}
